BEGIN;
DO $test$
DECLARE t uuid:=gen_random_uuid();u uuid:=gen_random_uuid();site uuid:=gen_random_uuid();depot uuid:=gen_random_uuid();art uuid:=gen_random_uuid();cust uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();w uuid:=gen_random_uuid();qid uuid;sid uuid;li uuid;tok uuid;v text;r jsonb;items jsonb;req text:=gen_random_uuid()::text;ret uuid;other jsonb;opts jsonb;
BEGIN
 INSERT INTO public.tenants(id,name,enabled_modules,settings) VALUES(t,'RECETTE MULTI LOT TVA','[]','{"stock_method":"lot"}');
 INSERT INTO auth.users(id,email,aud,role) VALUES(u,u::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.profiles(id,tenant_id,role,site_access_mode,full_name,is_active) VALUES(u,t,'admin','all','Commercial recette',true) ON CONFLICT(id) DO UPDATE SET tenant_id=excluded.tenant_id,role=excluded.role,site_access_mode=excluded.site_access_mode,is_active=true;
 INSERT INTO public.sites(id,tenant_id,name,is_active,allow_negative_stock) VALUES(site,t,'Magasin recette',true,false);
 INSERT INTO public.sites(id,tenant_id,name,is_active,is_warehouse,parent_site_id,allow_negative_stock) VALUES(depot,t,'Dépôt recette',true,true,site,false);
 INSERT INTO public.articles(id,tenant_id,internal_ref,name,sale_price,purchase_price,track_stock,vat_rate) VALUES(art,t,'REC-001','Article recette',1000,500,true,18);
 INSERT INTO public.customers(id,tenant_id,name) VALUES(cust,t,'Client recette');
 INSERT INTO public.stock_levels(tenant_id,article_id,site_id,quantity) VALUES(t,art,depot,10),(t,art,site,99);
 INSERT INTO public.stock_lots(id,tenant_id,article_id,site_id,batch_number,expiry_date,initial_quantity,remaining_quantity,purchase_price) VALUES(a,t,art,depot,'A001',current_date+30,6,6,400),(b,t,art,depot,'B002',current_date+60,4,4,600);
 INSERT INTO public.sales_vat_settings(tenant_id,site_id,enabled) VALUES(t,site,true);
 PERFORM set_config('request.jwt.claim.sub',u::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.create_quote_atomic(t,site,cust,NULL,'','{}',NULL,jsonb_build_array(jsonb_build_object('article_id',art,'name','Article recette','quantity',10,'unit_price',1000,'discount',0)),gen_random_uuid());qid:=(r->'quote'->>'id')::uuid;v:=r->>'version';
 r:=public.document_edit_lease(t,'quote',qid::text,w,'acquire');tok:=(r->>'token')::uuid;
 r:=public.change_locked_quote_status(t,qid,v,'accepted',w,tok);v:=r->>'version';
 r:=public.document_edit_lease(t,'quote',qid::text,w,'acquire');tok:=(r->>'token')::uuid;
 r:=public.convert_quote_atomic(t,qid,w,tok,v,depot,NULL,'[{"expected_ttc":11800}]',jsonb_build_object(art::text,jsonb_build_array(jsonb_build_object('lot_id',a,'quantity',6),jsonb_build_object('lot_id',b,'quantity',4))));sid:=(r->>'sale_id')::uuid;
 EXECUTE 'RESET ROLE'; SET CONSTRAINTS ALL IMMEDIATE;
 SELECT id INTO STRICT li FROM public.sale_items WHERE tenant_id=t AND sale_id=sid;
 UPDATE public.stock_lots SET purchase_price=999 WHERE id IN (a,b);
 IF NOT EXISTS(SELECT 1 FROM public.sales WHERE id=sid AND site_id=site AND vat_net_amount=10000 AND status IN ('validated','partial','paid')) THEN RAISE EXCEPTION 'Facture fiscale non finalisée : %',(SELECT jsonb_build_object('site',site_id,'status',status,'ht',vat_net_amount,'total',total) FROM public.sales WHERE id=sid);END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 opts:=public.read_fiscal_return_lots(sid)->li::text;
 IF jsonb_array_length(opts)<>2 THEN RAISE EXCEPTION 'Options absentes';END IF;
 items:=jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',3,'lots',jsonb_build_array(jsonb_build_object('lot_id',a,'quantity',2),jsonb_build_object('lot_id',b,'quantity',1))));
 BEGIN PERFORM public.prepare_vat_invoice_return(sid,site,jsonb_set(items,'{0,lots,0,quantity}','3'),'Retour',true,req,true);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Quantité erronée acceptée';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 r:=public.prepare_vat_invoice_return(sid,site,items,'Retour',true,req,true);ret:=(r->>'id')::uuid;
 IF (r->>'total')::numeric<>3540 OR (r->>'vat_amount')::numeric<>540 THEN RAISE EXCEPTION 'TVA incorrecte';END IF;
 r:=public.prepare_vat_invoice_return(sid,site,items,'Retour',true,req,true);
 IF (r->>'id')::uuid IS DISTINCT FROM ret THEN RAISE EXCEPTION 'Doublon';END IF;
 other:=jsonb_set(jsonb_set(items,'{0,lots,0,quantity}','1'),'{0,lots,1,quantity}','2');
 BEGIN PERFORM public.prepare_vat_invoice_return(sid,site,other,'Retour',true,req,true);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Payload modifié accepté';EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Référence de traitement déjà%' THEN RAISE;END IF;END;
 EXECUTE 'RESET ROLE';
 IF (SELECT remaining_quantity FROM public.stock_lots WHERE id=a)<>2 OR (SELECT remaining_quantity FROM public.stock_lots WHERE id=b)<>1 OR (SELECT quantity FROM public.stock_levels WHERE tenant_id=t AND site_id=depot AND article_id=art)<>3 THEN RAISE EXCEPTION 'Restitution partielle incorrecte';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 opts:=public.read_fiscal_return_lots(sid)->li::text;
 IF (SELECT sum((x->>'available')::numeric) FROM jsonb_array_elements(opts) x)<>7 THEN RAISE EXCEPTION 'Disponible incorrect';END IF;
 other:=jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',1,'lots',jsonb_build_array(jsonb_build_object('lot_id',b,'quantity',1))));
 PERFORM public.prepare_vat_invoice_return(sid,site,other,'Avoir sans stock',false,gen_random_uuid()::text,true);
 other:=jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',3,'lots',jsonb_build_array(jsonb_build_object('lot_id',b,'quantity',3))));
 BEGIN PERFORM public.prepare_vat_invoice_return(sid,site,other,'Dépassement lot',true,gen_random_uuid()::text,true);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Dépassement accepté';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 other:=jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',6));
 PERFORM public.prepare_vat_invoice_return(sid,site,other,'Solde',true,gen_random_uuid()::text,true);
 EXECUTE 'RESET ROLE';
 IF (SELECT remaining_quantity FROM public.stock_lots WHERE id=a)<>6 OR (SELECT remaining_quantity FROM public.stock_lots WHERE id=b)<>3 OR (SELECT quantity FROM public.stock_levels WHERE tenant_id=t AND site_id=depot AND article_id=art)<>9 OR (SELECT quantity FROM public.stock_levels WHERE tenant_id=t AND site_id=site AND article_id=art)<>99 OR (SELECT sum(total) FROM public.sale_returns WHERE sale_id=sid)<>11800 OR (SELECT sum(vat_amount) FROM public.sale_returns WHERE sale_id=sid)<>1800 OR (SELECT sum(quantity) FROM public.sale_return_lot_allocations WHERE tenant_id=t)<>10 OR (SELECT sum(quantity) FROM public.sale_return_lot_allocations WHERE tenant_id=t AND restocked)<>9 THEN RAISE EXCEPTION 'Cumul incohérent';END IF;
 IF abs((SELECT sum(quantity*purchase_cost) FROM public.sale_return_items WHERE return_id=ret)-1400)>0.000001 OR (SELECT sum(quantity*purchase_price) FROM public.sale_return_lot_allocations WHERE tenant_id=t)<>4800 OR (SELECT sum(quantity*purchase_price) FROM public.sale_return_lot_allocations WHERE tenant_id=t AND restocked)<>4200 THEN RAISE EXCEPTION 'Valorisation historique incorrecte';END IF;
END $test$;
ROLLBACK;

